 57:   when: ovos_performance_tuning_rt_cpu_affinity | default('') == ''
 58: 
 59: - name: Use configured CPU affinity for latency-critical services
 60:   ansible.builtin.set_fact:
 61:     ovos_performance_tuning_rt_cpu_affinity_effective: "{{ ovos_performance_tuning_rt_cpu_affinity }}"
 62:   when: ovos_performance_tuning_rt_cpu_affinity | default('') | length > 0
 63: 
 64: - name: Apply RT scheduling and CPU affinity to OVOS services
 65:   ansible.builtin.copy:
 66:     dest: "{{ ovos_installer_systemd_dropin_path }}/{{ item }}.service.d/{{ ovos_performance_tuning_rt_dropin_name }}"
 67:     content: |
 68:       [Service]
 69:       {% if (ovos_installer_systemd_scope | default('user')) == 'system' %}
 70:       AmbientCapabilities=CAP_SYS_NICE
 71:       CapabilityBoundingSet=CAP_SYS_NICE
 72:       {% endif %}
 73:       CPUSchedulingPolicy={{ ovos_performance_tuning_rt_policy }}
 74:       CPUSchedulingPriority={{ ovos_performance_tuning_rt_priority }}
 75:       LimitRTPRIO={{ ovos_performance_tuning_rt_limit_rtprio }}
 76:       LimitMEMLOCK={{ ovos_performance_tuning_rt_limit_memlock }}
 77:       {% if ovos_performance_tuning_rt_cpu_affinity_effective | length > 0 %}
 78:       CPUAffinity={{ ovos_performance_tuning_rt_cpu_affinity_effective }}
 79:       {% endif %}
 80:     owner: "{{ ovos_installer_systemd_dropin_owner }}"
 81:     group: "{{ ovos_installer_systemd_dropin_group }}"
 82:     mode: '0644'
 83:   notify:
 84:     - "{{ ovos_installer_systemd_reload_handler }}"
 85:     - Restart OVOS services
 86:   loop: "{{ ovos_performance_tuning_rt_services }}"
 87: 
 88: - name: Apply RT scheduling and CPU affinity to WirePlumber
 89:   ansible.builtin.copy:
 90:     dest: "{{ ovos_installer_systemd_dropin_user_path }}/wireplumber.service.d/{{ ovos_performance_tuning_rt_dropin_name }}"
 91:     content: |
 92:       [Service]
 93:       CPUSchedulingPolicy={{ ovos_performance_tuning_rt_policy }}
 94:       CPUSchedulingPriority={{ ovos_performance_tuning_rt_priority }}
 95:       LimitRTPRIO={{ ovos_performance_tuning_rt_limit_rtprio }}
 96:       LimitMEMLOCK={{ ovos_performance_tuning_rt_limit_memlock }}
 97:       {% if ovos_performance_tuning_rt_cpu_affinity_effective | length > 0 %}
 98:       CPUAffinity={{ ovos_performance_tuning_rt_cpu_affinity_effective }}
 99:       {% endif %}
100:     owner: "{{ ovos_installer_user }}"
101:     group: "{{ ovos_installer_group }}"
102:     mode: '0644'
103:   notify:
104:     - Reload Systemd User
105:     - Restart OVOS services

 1: - name: Check if subvolume exists {{ subvolume_loop_var + ' of ' + storage_loop_var }}
 2:   ansible.builtin.stat:
 3:     path: /mnt/disks/storage/{{ subvolume_loop_var }}/{{ storage_loop_var }}
 4:   register: subvolume_data_status
 5: 
 6: - name: Mount root subvolume for {{ subvolume_loop_var + ' of ' + storage_loop_var }}
 7:   ansible.posix.mount:
 8:     path: /mnt/disks/storage/root/{{ storage_loop_var }}
 9:     src: /dev/disk/by-id/{{ storage_loop_var }}-part1
10:     fstype: btrfs
11:     state: mounted
12: 
13: - name: Check if subvolume exists {{ subvolume_loop_var + ' of ' + storage_loop_var }}
14:   ansible.builtin.stat:
15:     path: /mnt/disks/storage/root/{{ storage_loop_var }}/{{ subvolume_loop_var }}
16:   register: subvolume_loop_data_status
17: 
18: - name: Create subvolume if not exists {{ subvolume_loop_var + ' of ' + storage_loop_var }}
19:   changed_when: false
20:   ansible.builtin.command: btrfs subvolume create ./{{ subvolume_loop_var }}
21:   args:
22:     chdir: /mnt/disks/storage/root/{{ storage_loop_var }}
23:   when: not subvolume_loop_data_status.stat.exists
24: 
25: - name: Mount subvolume for {{ subvolume_loop_var + ' of ' + storage_loop_var }}
26:   ansible.posix.mount:
27:     path: /mnt/disks/storage/{{ subvolume_loop_var }}/{{ storage_loop_var }}
28:     src: /dev/disk/by-id/{{ storage_loop_var }}-part1
29:     fstype: btrfs
30:     opts: subvol=/{{ subvolume_loop_var }},compress=zstd:1
31:     state: mounted
